# -*- coding: utf-8 -*-
S = "полный обзор задач 11 класса (очередь G9–G11), проверено вычислением; условия сверены с текстом учебника"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
E("G11_TB_11_5*_11_25_в", r"артефакт OCR: в условии стояла нелепая степень $^{3/3}$ у логарифма ($3/3=1$); ключ $(-\sqrt5;-1)\cup(1;\sqrt5)$ соответствует $\log_{0{,}5}(x^{2}-1)>-2$",
  q=r"Решите неравенство: $\log_{0{,}5}(x^{2}-1) > -2$",
  dnew={0: (r"$x \in (-\sqrt{5}; \sqrt{5})$", "Ученик перешёл к неравенству $0<x^{2}-1<4$, но не исключил отрезок $[-1;1]$, где $x^{2}-1\\le0$ и логарифм не определён."),
        1: (r"$x \in (-\infty; -\sqrt{5}) \cup (\sqrt{5}; +\infty)$", "Ученик не сменил знак неравенства при основании $0{,}5\\in(0;1)$ и получил $x^{2}-1>4$."),
        2: (r"$x \in (-\sqrt{3}; -1) \cup (1; \sqrt{3})$", "Ученик вычислил $0{,}5^{-2}=2$ вместо $4$ и получил $x^{2}-1<2$.")})
E("G11_TB_11_5*_11_25_г", r"артефакт OCR: в условии стояла нелепая степень $^{3/3}$ у логарифма; ключ соответствует $\log_{0{,}5}(x^{2}+1)<-1$",
  q=r"Решите неравенство: $\log_{0{,}5}(x^{2}+1) < -1$",
  dnew={0: (r"$x \in (-1; 1)$", "Ученик не сменил знак неравенства при основании $0{,}5\\in(0;1)$ и получил $x^{2}+1<2$."),
        1: (r"$x \in (-\infty; -\sqrt{2}) \cup (\sqrt{2}; +\infty)$", "Ученик из $x^{2}+1>2$ получил $x^{2}>2$, потеряв вычитание единицы."),
        2: (r"$x \in (-\infty; 0) \cup (0; +\infty)$", "Ученик заметил, что $x^{2}+1>0$ при любом $x$, и не решил неравенство $x^{2}+1>2$.")})
E("G11_TB_11_7*_11_53_1", r"$\sin^2x+\sin2x-3\cos^2x=\cos^2x(\tg x-1)(\tg x+3)\ge0$ на $(\frac\pi4;\frac{5\pi}4)$ только при $x\in(\frac\pi4;\pi-\arctg3]$; при $x\in(\pi-\arctg3;\pi]$ и $[\pi;\frac{5\pi}4)$ подкоренное выражение отрицательно ($x=\pi$: $-3$); $x=\frac\pi2$ входит в решение ($\sqrt1=1>-1$); в ключе стояло лишнее $[\pi;\frac{5\pi}4)$ и выколота $\frac\pi2$; при $x=\pi-\arctg3$ левая часть $0>$ правой (отрицательной), конец включён",
  k=r"$\left(\dfrac{\pi}{4}; \pi - \arctg 3\right]$",
  dnew={0: (r"$(\dfrac{\pi}{4}; \pi - \arctg 3] \cup [\pi; \dfrac{5\pi}{4})$", "Ученик включил промежуток $[\\pi;\\frac{5\\pi}{4})$, где правая часть отрицательна, но подкоренное выражение тоже отрицательно (при $x=\\pi$ оно равно $-3$), то есть выражение не определено."),
        1: (r"$(\dfrac{\pi}{4}; \dfrac{\pi}{2}) \cup (\dfrac{\pi}{2}; \pi - \arctg 3]$", "Ученик выколол точку $\\frac{\\pi}{2}$, где не определён $\\tg x$, но в исходном неравенстве тангенса нет: при $x=\\frac{\\pi}{2}$ имеем $\\sqrt{1}=1>-1$."),
        2: (r"$\left( \dfrac{\pi}{4}; \dfrac{\pi}{2} \right) \cup \left( \dfrac{\pi}{2}; \pi - \arctg 3 \right] \cup \left( \pi; \dfrac{5\pi}{4} \right)$", "Ученик решил, что на $(\\pi;\\frac{5\\pi}{4})$ правая часть отрицательна, значит неравенство верно, но не проверил область определения: там подкоренное выражение отрицательно.")})
E("G11_TB_11_7*_11_53_2", r"$\sin^2x-2\sin2x+3\cos^2x=\cos^2x(\tg x-1)(\tg x-3)\ge0$ на $(\frac{5\pi}4;\frac{9\pi}4)$ только при $x\ge\pi+\arctg3$; там правая часть $\sin x-\cos x<0$ (проверено вычислением), так что решение $(\pi+\arctg3;\frac{9\pi}4)$; прежний ключ обрывался на $\frac{7\pi}4$ и включал $(\frac{5\pi}4;\pi+\arctg3)$, где подкоренное выражение отрицательно",
  k=r"$\left(\pi + \arctg 3; \dfrac{9\pi}{4}\right)$",
  dnew={0: (r"$\left(\dfrac{5\pi}{4}; \dfrac{7\pi}{4}\right)$", "Ученик не проверил область определения: на $\\left(\\frac{5\\pi}{4};\\pi+\\arctg3\\right)$ подкоренное выражение $\\cos^{2}x(\\tg x-1)(\\tg x-3)$ отрицательно; и оборвал ответ на $\\frac{7\\pi}{4}$."),
        1: (r"$\left(\pi + \arctg 3; \dfrac{7\pi}{4}\right)$", "Ученик верно нашёл начало $\\pi+\\arctg3$ из условия $\\tg x\\ge3$, но границу взял $\\frac{7\\pi}{4}$ вместо $\\frac{9\\pi}{4}$: при $x\\in[\\frac{7\\pi}{4};\\frac{9\\pi}{4})$ неравенство тоже верно."),
        2: (r"$(\pi; \dfrac{5\pi}{4}) \cup (\dfrac{7\pi}{4}; 2\pi)$", "Ученик отобрал значения вне заданного промежутка $\\left(\\frac{5\\pi}{4};\\frac{9\\pi}{4}\\right)$ и не проверил область определения корня.")})
